import numpy as np, json
from scipy import ndimage
# use saved meta for camera cal
meta=json.load(open('/app/output/closed5/meta.json'))
for cam in ['front','right','topview']:
 im=np.array(Image.open(f'/app/output/closed5/last/{cam}.jpg'))
 d=np.load(f'/app/output/closed5/depth/{cam}.npy').astype(float);d=d[0] if d.ndim==3 else d
 K=np.array(meta['cameras'][cam]['intrinsic_cv']);M=np.array(meta['cameras'][cam]['cam2world_gl']);
 R,G,B=[im[:,:,i].astype(int) for i in range(3)]
 masks={'cyan':(G>100)&(B>100)&(G>R*1.3)&(B>R*1.3),'green':(G>100)&(G>R*1.25)&(G>B*1.2)&(R<180)}
 print('\n',cam)
 for label,m in masks.items():
  if cam=='front':
   m[:100]=0;m[145:]=0;m[:,:105]=0;m[:,190:]=0
  if cam=='right':
   m[:110]=0;m[180:]=0;m[:,:135]=0;m[:,185:]=0
  if cam=='topview':
   m[:65]=0;m[115:]=0;m[:,:140]=0;m[:,220:]=0
  lab,n=ndimage.label(m)
  for i in range(1,n+1):
   ys,xs=np.where(lab==i)
   if len(xs)<2:continue
   pts=[]
   for u,v in zip(xs,ys):
    z=d[v,u];cv=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);w=M@cv;pts.append(w[:3])
   pts=np.array(pts)
   print(label,len(xs),'uv',(xs.min(),ys.min(),xs.max(),ys.max()),'med world',np.median(pts,axis=0),'q',np.quantile(pts,[.1,.9],axis=0))
